VALUES('01fe19996eb141c79c8efaa48aa54b25','开放式理财产品在前一估值日内，产品资产净值中不具备活跃交易市场或者在活跃市场中无报价，且不能采用估值技术可靠计量公允价值的资产占比，应小于50%(穿透后)','LIMIT_CONCENT','${BJBHYJYSCBNJLGYJZZCGZCTH}/${CPJZCJZ}','SUPERVISION','03','DAYTIME,DAYEND', null , '{"threshold_1":{"op":">=","value":"45","unit":"PERCENT","is_model":"02"}}' , '{"threshold_1":{"op":">=","unit":"PERCENT","is_model":"02"}}'  , '{"threshold_1":{"op":">=","value":"50","unit":"PERCENT","is_model":"02"}}' , 'N' , null , '01' , null ,'system',null,sysdate,'system',sysdate, '02' , null , null , null  , null , null  , 'Y' , '《理财公司理财产品流动性风险管理办法》中国银行保险监督管理委员会令〔2021〕14号第三十条 开放式理财产品在前一估值日内，产品资产净值50%以上的资产不具备活跃交易市场或者在活跃市场中无报价，且不能采用估值技术可靠计量公允价值的，理财公司应当暂停该产品估值，并采取延缓支付赎回款项或暂停接受理财产品认购、赎回申请等措施。' , 'SUP102092' );
